        "python": sys.version.split()[0],
        "tenant": cfg.tenant.id if cfg else "",
        "app_env": cfg.ops.app_env if cfg else "",
        "llm_mode": cfg.llm.mode if cfg else "",
        "channels": channels,
        "modules": {
            "memory": cfg.memory.enabled if cfg else False,
            "fleet": cfg.fleet.enabled if cfg else False,
            "calendar": cfg.calendar.enabled if cfg else False,
            "backup": cfg.ops.backup_enabled if cfg else False,
        },
        "uptime_s": round(time.time() - STARTED_AT, 1),
    }

"""Structured logging (JSON lines for Railway drains) + audit-friendly records."""

from __future__ import annotations

import json
import logging
import sys
import time
from typing import Any

_CONFIGURED = False


class JsonFormatter(logging.Formatter):
    def __init__(self, tenant_id: str = "") -> None:
        super().__init__()
        self.tenant_id = tenant_id

    def format(self, record: logging.LogRecord) -> str:
        payload: dict[str, Any] = {
            "ts": f"{time.time():.3f}",
            "level": record.levelname,
            "logger": record.name,
            "msg": record.getMessage(),
            "tenant": self.tenant_id,
        }
        # Correlate every log line with the HTTP request that produced it.
        # Imported lazily to keep logging_setup free of app-level imports.
        try:
            from app.observability import current_request_id

            rid = current_request_id()
            if rid:
                payload["request_id"] = rid
        except Exception:
            payload["request_id"] = None
        for key in (
            "conversation_id",
            "approval_id",
            "channel",
            "actor",
            "action",
            "entity",
            "latency_ms",
            "cost_usd",
            "reason",
            "error",
        ):
            value = getattr(record, key, None)
            if value is not None:
                payload[key] = value
        if record.exc_info:
            payload["exc"] = self.formatException(record.exc_info)
        return json.dumps(payload, ensure_ascii=False, default=str)


class TextFormatter(logging.Formatter):
    def __init__(self, tenant_id: str = "") -> None:
        super().__init__(fmt="%(asctime)s %(levelname)-7s [%(tenant)s] %(name)s: %(message)s")
        self.tenant_id = tenant_id

    def format(self, record: logging.LogRecord) -> str:
        if not hasattr(record, "tenant"):
            record.tenant = self.tenant_id
        return super().format(record)


class TenantFilter(logging.Filter):
    def __init__(self, tenant_id: str) -> None:
        super().__init__()
        self.tenant_id = tenant_id

    def filter(self, record: logging.LogRecord) -> bool:
        if not hasattr(record, "tenant"):
            record.tenant = self.tenant_id
        return True


def setup_logging(level: str = "INFO", *, json_enabled: bool = True, tenant_id: str = "") -> None:
    global _CONFIGURED
    root = logging.getLogger()
    root.setLevel(getattr(logging, level.upper(), logging.INFO))
    for handler in list(root.handlers):
        root.removeHandler(handler)
    handler = logging.StreamHandler(sys.stdout)
    handler.setFormatter(JsonFormatter(tenant_id) if json_enabled else TextFormatter(tenant_id))
    handler.addFilter(TenantFilter(tenant_id))
    root.addHandler(handler)
    for noisy in ("httpx", "httpcore", "aiogram", "botocore", "asyncio", "urllib3"):
        logging.getLogger(noisy).setLevel(logging.WARNING)
    # uvicorn installs its own stderr handlers; Railway shows every stderr line
    # as "error" even for a plain INFO access log. Strip them so uvicorn lines
    # flow through the root JSON handler on stdout with their real severity.
    for name in ("uvicorn", "uvicorn.error", "uvicorn.access", "uvicorn.asgi"):
        ulog = logging.getLogger(name)
        for handler in list(ulog.handlers):
            ulog.removeHandler(handler)
        ulog.propagate = True
    _CONFIGURED = True


def configured() -> bool:
    return _CONFIGURED


def get_logger(name: str, **bound: Any) -> logging.LoggerAdapter:
    return logging.LoggerAdapter(logging.getLogger(name), dict(bound))

"""Observability: request correlation, RED metrics and a Prometheus endpoint.

The platform already emits structured JSON logs, but before this module there
was no way to answer "how many requests, how slow, how many errors" without
grepping. This adds three things, all dependency-free:

1. ``RequestContextMiddleware`` — assigns every request an ``X-Request-ID``
   (honouring an inbound one so a trace survives a proxy hop), exposes it via a
   ``ContextVar`` so any log line can be correlated, and records latency.
2. ``MetricsRegistry`` — an in-process counter/histogram store implementing the
   RED method (Rate, Errors, Duration) with Prometheus text exposition.
3. ``/metrics`` — the scrape endpoint, and ``/metrics.json`` for humans.

Cardinality is deliberately bounded: metrics are keyed on the *route template*
(``/admin/api/catalog/products/{product_id}``) rather than the raw path, so a
million distinct product ids cannot explode the series count.
"""

from __future__ import annotations

import time
import uuid
from collections.abc import Iterable
from contextvars import ContextVar
from threading import Lock
from typing import Any

from fastapi import APIRouter, Request, Response
from starlette.middleware.base import BaseHTTPMiddleware

from app.logging_setup import get_logger

log = get_logger("app.observability")

REQUEST_ID_HEADER = "X-Request-ID"

#: Correlation id for the request currently being served, if any.
request_id_var: ContextVar[str] = ContextVar("request_id", default="")

#: Latency buckets in seconds (Prometheus cumulative histogram).
DEFAULT_BUCKETS: tuple[float, ...] = (
    0.005,
    0.01,
    0.025,
    0.05,
    0.1,
    0.25,
    0.5,
    1.0,
    2.5,
    5.0,
    10.0,
)


def current_request_id() -> str:
    """Return the correlation id of the in-flight request ("" outside one)."""
    return request_id_var.get()


def _escape(value: str) -> str:
    return value.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")


def _format_labels(labels: tuple[tuple[str, str], ...]) -> str:
    if not labels:
        return ""
    inner = ",".join(f'{k}="{_escape(v)}"' for k, v in labels)
    return "{" + inner + "}"


class MetricsRegistry:
    """A small, thread-safe counter/gauge/histogram registry.

    Deliberately in-process: the platform runs one app per container and the
    scrape endpoint is per-instance, which is exactly what Prometheus expects.
    """

    def __init__(self, buckets: Iterable[float] = DEFAULT_BUCKETS) -> None:
        self._lock = Lock()
        self._buckets = tuple(sorted(buckets))
        self._counters: dict[tuple[str, tuple[tuple[str, str], ...]], float] = {}
        self._gauges: dict[tuple[str, tuple[tuple[str, str], ...]], float] = {}
        self._hist_counts: dict[tuple[str, tuple[tuple[str, str], ...]], list[int]] = {}
        self._hist_sum: dict[tuple[str, tuple[tuple[str, str], ...]], float] = {}
        self._help: dict[str, str] = {}

    # -- recording ---------------------------------------------------------

    @staticmethod
    def _key(name: str, labels: dict[str, str] | None):
        return name, tuple(sorted((labels or {}).items()))

    def describe(self, name: str, help_text: str) -> None:
        self._help[name] = help_text

    def inc(self, name: str, labels: dict[str, str] | None = None, value: float = 1.0) -> None:
        key = self._key(name, labels)
        with self._lock:
            self._counters[key] = self._counters.get(key, 0.0) + value

    def set_gauge(self, name: str, value: float, labels: dict[str, str] | None = None) -> None:
        key = self._key(name, labels)
        with self._lock:
            self._gauges[key] = value

    def observe(self, name: str, value: float, labels: dict[str, str] | None = None) -> None:
        key = self._key(name, labels)
        with self._lock:
            counts = self._hist_counts.get(key)
            if counts is None:
                counts = [0] * (len(self._buckets) + 1)
                self._hist_counts[key] = counts
                self._hist_sum[key] = 0.0
            placed = False
            for i, bound in enumerate(self._buckets):
                if value <= bound:
                    counts[i] += 1
                    placed = True
                    break
            if not placed:
                counts[-1] += 1
            self._hist_sum[key] += value

    def reset(self) -> None:
        with self._lock:
            self._counters.clear()
            self._gauges.clear()
            self._hist_counts.clear()
            self._hist_sum.clear()

    # -- reading -----------------------------------------------------------

    def counter_value(self, name: str, labels: dict[str, str] | None = None) -> float:
        with self._lock:
            return self._counters.get(self._key(name, labels), 0.0)

    def histogram_count(self, name: str, labels: dict[str, str] | None = None) -> int:
        with self._lock:
            return sum(self._hist_counts.get(self._key(name, labels), []))

    def snapshot(self) -> dict[str, Any]:
        """A JSON-friendly view of every series, for humans and for tests."""
        with self._lock:
            counters = [
                {"name": n, "labels": dict(l), "value": v}
                for (n, l), v in sorted(self._counters.items())
            ]
            gauges = [
                {"name": n, "labels": dict(l), "value": v}
                for (n, l), v in sorted(self._gauges.items())
            ]
            histograms = []
            for (n, l), counts in sorted(self._hist_counts.items()):
                total = sum(counts)
                hsum = self._hist_sum[(n, l)]
                histograms.append(
                    {
                        "name": n,
                        "labels": dict(l),
                        "count": total,
                        "sum": round(hsum, 6),
                        "avg": round(hsum / total, 6) if total else 0.0,
                    }
                )
        return {"counters": counters, "gauges": gauges, "histograms": histograms}

    def render_prometheus(self) -> str:
        """Render the registry in the Prometheus text exposition format."""
        lines: list[str] = []
        with self._lock:
            names_done: set[str] = set()

            for (name, labels), value in sorted(self._counters.items()):
                if name not in names_done:
                    if name in self._help:
                        lines.append(f"# HELP {name} {self._help[name]}")
                    lines.append(f"# TYPE {name} counter")
                    names_done.add(name)
                lines.append(f"{name}{_format_labels(labels)} {value}")

            for (name, labels), value in sorted(self._gauges.items()):
                if name not in names_done:
                    if name in self._help:
                        lines.append(f"# HELP {name} {self._help[name]}")
                    lines.append(f"# TYPE {name} gauge")
                    names_done.add(name)
                lines.append(f"{name}{_format_labels(labels)} {value}")

            for (name, labels), counts in sorted(self._hist_counts.items()):
                if name not in names_done:
                    if name in self._help:
                        lines.append(f"# HELP {name} {self._help[name]}")
                    lines.append(f"# TYPE {name} histogram")
                    names_done.add(name)
                cumulative = 0
                for i, bound in enumerate(self._buckets):
                    cumulative += counts[i]
                    bucket_labels = labels + (("le", str(bound)),)
                    lines.append(f"{name}_bucket{_format_labels(bucket_labels)} {cumulative}")
                cumulative += counts[-1]
                inf_labels = labels + (("le", "+Inf"),)
                lines.append(f"{name}_bucket{_format_labels(inf_labels)} {cumulative}")
                lines.append(f"{name}_sum{_format_labels(labels)} {self._hist_sum[(name, labels)]}")
                lines.append(f"{name}_count{_format_labels(labels)} {cumulative}")

        return "\n".join(lines) + "\n"


#: The process-wide registry.
registry = MetricsRegistry()

registry.describe(
    "Zenovix-Agent_http_requests_total", "Total HTTP requests by route, method and status."
)
registry.describe("Zenovix-Agent_http_request_duration_seconds", "HTTP request latency in seconds.")
registry.describe("Zenovix-Agent_http_requests_in_flight", "Requests currently being served.")
registry.describe(
    "Zenovix-Agent_http_exceptions_total", "Unhandled exceptions raised while serving a request."
)


def route_template(request: Request) -> str:
    """The matched route pattern, not the concrete path.

    Keeps metric cardinality bounded: ``/products/{product_id}`` stays one
    series no matter how many products exist.
    """
    route = request.scope.get("route")
    path = getattr(route, "path", None)
    if path:
        return str(path)
    return "unmatched"


class RequestContextMiddleware(BaseHTTPMiddleware):
    """Assign a correlation id and record RED metrics for every request."""

    def __init__(self, app: Any, metrics: MetricsRegistry | None = None) -> None:
        super().__init__(app)
        self._metrics = metrics if metrics is not None else registry

    async def dispatch(self, request: Request, call_next: Any) -> Response:
        incoming = request.headers.get(REQUEST_ID_HEADER, "").strip()
        rid = incoming or uuid.uuid4().hex
        token = request_id_var.set(rid)
        request.state.request_id = rid

        self._metrics.inc("Zenovix-Agent_http_requests_in_flight", value=1)
        started = time.perf_counter()
        status = 500
        try:
            response = await call_next(request)
            status = response.status_code
            response.headers[REQUEST_ID_HEADER] = rid
            return response
        except Exception:
            self._metrics.inc(
                "Zenovix-Agent_http_exceptions_total",
                {"route": route_template(request), "method": request.method},
            )
            raise
        finally:
            elapsed = time.perf_counter() - started
            labels = {"route": route_template(request), "method": request.method}
            self._metrics.inc("Zenovix-Agent_http_requests_in_flight", value=-1)
            self._metrics.inc(
                "Zenovix-Agent_http_requests_total", {**labels, "status": str(status)}
            )
            self._metrics.observe("Zenovix-Agent_http_request_duration_seconds", elapsed, labels)
            request_id_var.reset(token)


router = APIRouter(tags=["observability"])


@router.get("/metrics", response_class=Response)
async def metrics_endpoint() -> Response:
    """Prometheus scrape endpoint (text exposition format)."""
    return Response(
        content=registry.render_prometheus(),
        media_type="text/plain; version=0.0.4; charset=utf-8",
    )


@router.get("/metrics.json")
async def metrics_json() -> dict[str, Any]:
    """The same series as ``/metrics``, as JSON, for dashboards and debugging."""
    return registry.snapshot()

#!/usr/bin/env python3
"""Configuration linter — validates all environment variables against the contract.

Checks:
1. Required variables are present
2. Types are correct (int, float, bool, enum)
3. Ranges are valid
4. No leftover placeholder values
5. Secrets are sufficiently long

Run: python tools/config_lint.py
Exit code 0 = clean, 1 = errors found.
"""

from __future__ import annotations

import os
import sys
from pathlib import Path

# ---------------------------------------------------------------------------
# Validation rules
# ---------------------------------------------------------------------------

