    "TENANT_ID",
    "SUPPORT_CONTACT",
    "TELEGRAM_BOT_TOKEN",
    "TELEGRAM_ADMIN_IDS",
    "DATABASE_URL",
    "REDIS_URL",
    "R2_ENDPOINT",
