  --bg-card-hover: #1a2332;
  --bg-input: #0f1520;
  --bg-sidebar: #0d1117;
  --border: #1e293b;
  --border-focus: #e0a33e;
  --text: #e5e7eb;
  --text-dim: #9ca3af;
  --text-bright: #f9fafb;
  --accent: #e0a33e;
  --accent-hover: #d4952f;
  --accent-dim: rgba(224, 163, 62, 0.15);
  --success: #10b981;
  --success-dim: rgba(16, 185, 129, 0.15);
  --warning: #f59e0b;
  --warning-dim: rgba(245, 158, 11, 0.15);
  --danger: #ef4444;
  --danger-dim: rgba(239, 68, 68, 0.15);
  --info: #3b82f6;
  --info-dim: rgba(59, 130, 246, 0.15);
  --radius: 8px;
  --radius-sm: 4px;
  --radius-lg: 12px;
  --shadow: 0 1px 3px rgba(0,0,0,0.3);
  --shadow-lg: 0 4px 12px rgba(0,0,0,0.4);
  --font: 'Segoe UI', Tahoma, 'Noto Sans Arabic', sans-serif;
  --font-mono: 'Cascadia Code', 'Fira Code', monospace;
  --sidebar-w: 260px;
  --top-h: 56px;
  --transition: 0.2s ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  overflow: hidden;
  height: 100%;
}

::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--text-dim); }

/* ── Boot (Login) ────────────────────────────────────────── */

.boot {
  position: fixed; inset: 0;
  display: flex; align-items: center; justify-content: center;
  background: var(--bg);
  z-index: 9999;
}

.boot-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 2.5rem;
  width: 100%; max-width: 400px;
  box-shadow: var(--shadow-lg);
  text-align: center;
}

.boot-card h1 {
  font-size: 1.75rem;
  color: var(--accent);
  margin-bottom: 0.25rem;
}

.boot-card .subtitle {
  color: var(--text-dim);
  font-size: 0.85rem;
  margin-bottom: 1.5rem;
}

.boot-card form { display: flex; flex-direction: column; gap: 1rem; }

.boot-card label {
  display: flex; flex-direction: column; gap: 0.35rem;
  text-align: start;
}

.boot-card label span {
  font-size: 0.8rem;
  color: var(--text-dim);
}

.boot-card input {
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text);
  padding: 0.65rem 0.85rem;
  font-size: 0.9rem;
  transition: border-color var(--transition);
}

.boot-card input:focus {
  outline: none;
  border-color: var(--border-focus);
}

.boot-card button[type="submit"] {
  background: var(--accent);
  color: #000;
  border: none;
  border-radius: var(--radius-sm);
  padding: 0.7rem;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--transition);
}

.boot-card button[type="submit"]:hover { background: var(--accent-hover); }

.error {
  color: var(--danger);
  font-size: 0.8rem;
  min-height: 1.2rem;
}

/* ── Shell Layout ────────────────────────────────────────── */

.shell {
  display: flex;
  height: 100vh;
  overflow: hidden;
}

.shell[hidden] { display: none; }

/* ── Sidebar ─────────────────────────────────────────────── */

.side {
  width: var(--sidebar-w);
  min-width: var(--sidebar-w);
  background: var(--bg-sidebar);
  border-inline-end: 1px solid var(--border);
  display: flex; flex-direction: column;
  overflow: hidden;
}

.brand {
  display: flex; align-items: center; gap: 0.6rem;
  padding: 1rem 1.2rem;
  border-block-end: 1px solid var(--border);
}

.brand strong {
  color: var(--accent);
  font-size: 1rem;
}

.brand .version {
  font-size: 0.65rem;
  color: var(--text-dim);
  background: var(--bg-card);
  padding: 0.15rem 0.45rem;
  border-radius: var(--radius-sm);
  margin-inline-start: auto;
}

#nav {
  flex: 1;
  overflow-y: auto;
  padding: 0.5rem 0;
}

.nav-btn {
  display: flex; align-items: center; gap: 0.65rem;
  width: 100%;
  padding: 0.65rem 1.2rem;
  background: none; border: none;
  color: var(--text-dim);
  font-size: 0.85rem;
  cursor: pointer;
  transition: all var(--transition);
  text-align: start;
}

.nav-btn:hover {
  background: var(--bg-card-hover);
  color: var(--text);
}

.nav-btn.active {
  background: var(--accent-dim);
  color: var(--accent);
  font-weight: 600;
}

.nav-btn .icon { font-size: 1.1rem; width: 1.5rem; text-align: center; }

.nav-btn .badge {
  margin-inline-start: auto;
  background: var(--danger);
  color: #fff;
  font-size: 0.65rem;
  font-weight: 700;
  padding: 0.1rem 0.45rem;
  border-radius: 99px;
  min-width: 1.2rem;
  text-align: center;
}

.side-foot {
  padding: 0.8rem 1.2rem;
  border-block-start: 1px solid var(--border);
}

.who {
  display: block;
  font-size: 0.75rem;
  color: var(--text-dim);
  margin-bottom: 0.5rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.side-actions {
  display: flex; gap: 0.5rem;
}

/* ── Main Area ───────────────────────────────────────────── */

.main {
  flex: 1;
  display: flex; flex-direction: column;
  overflow: hidden;
  min-width: 0;
}

.top {
  display: flex; align-items: center; justify-content: space-between;
  padding: 0.75rem 1.5rem;
  border-block-end: 1px solid var(--border);
  min-height: var(--top-h);
  flex-shrink: 0;
}

.top h2 {
  font-size: 1.05rem;
  color: var(--text-bright);
}

.top-right {
  display: flex; align-items: center; gap: 0.75rem;
}

.view {
  flex: 1;
  overflow-y: auto;
  padding: 1.5rem;
}

/* ── Buttons ─────────────────────────────────────────────── */

button, .btn {
  font-family: var(--font);
  font-size: 0.85rem;
  cursor: pointer;
  border: none;
  border-radius: var(--radius-sm);
  transition: all var(--transition);
}

.ghost {
  background: none;
  color: var(--text-dim);
  padding: 0.4rem 0.7rem;
}

.ghost:hover { background: var(--bg-card-hover); color: var(--text); }

.btn-primary {
  background: var(--accent);
  color: #000;
  font-weight: 600;
  padding: 0.5rem 1rem;
}

.btn-primary:hover { background: var(--accent-hover); }

.btn-secondary {
  background: var(--bg-card);
  color: var(--text);
  border: 1px solid var(--border);
  padding: 0.5rem 1rem;
}

.btn-secondary:hover { border-color: var(--text-dim); }

.btn-danger {
  background: var(--danger-dim);
  color: var(--danger);
  padding: 0.5rem 1rem;
}

.btn-danger:hover { background: var(--danger); color: #fff; }

.btn-success {
  background: var(--success-dim);
  color: var(--success);
  padding: 0.5rem 1rem;
}

.btn-success:hover { background: var(--success); color: #fff; }

.btn-sm { padding: 0.3rem 0.6rem; font-size: 0.75rem; }

/* ── Pills ───────────────────────────────────────────────── */

.pill {
  display: inline-flex; align-items: center; gap: 0.35rem;
  font-size: 0.7rem;
  padding: 0.25rem 0.6rem;
  border-radius: 99px;
  font-weight: 600;
  white-space: nowrap;
}

.pill-idle { background: var(--bg-card); color: var(--text-dim); }
.pill-ok { background: var(--success-dim); color: var(--success); }
.pill-warn { background: var(--warning-dim); color: var(--warning); }
.pill-err { background: var(--danger-dim); color: var(--danger); }

.pill::before {
  content: '';
  width: 6px; height: 6px;
  border-radius: 50%;
  background: currentColor;
}

/* ── Cards & Panels ──────────────────────────────────────── */

.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.25rem;
  margin-block-end: 1rem;
}

.card-header {
  display: flex; align-items: center; justify-content: space-between;
  margin-block-end: 1rem;
}

.card-header h3 {
  font-size: 0.95rem;
  color: var(--text-bright);
}

.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem; }

.stat-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1rem;
  text-align: center;
}

.stat-card .value {
  font-size: 1.8rem;
  font-weight: 700;
  color: var(--accent);
}

.stat-card .label {
  font-size: 0.75rem;
  color: var(--text-dim);
  margin-top: 0.25rem;
}

/* ── Tables ──────────────────────────────────────────────── */

.table-wrap {
  overflow-x: auto;
  border: 1px solid var(--border);
  border-radius: var(--radius);
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.85rem;
}

th, td {
  padding: 0.65rem 0.85rem;
  text-align: start;
  border-block-end: 1px solid var(--border);
}

th {
  background: var(--bg-sidebar);
  color: var(--text-dim);
  font-weight: 600;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  position: sticky;
  top: 0;
  z-index: 1;
}

tr:hover td { background: var(--bg-card-hover); }

/* ── Forms ───────────────────────────────────────────────── */

.form-group {
  margin-block-end: 1rem;
}

.form-group label {
  display: block;
  font-size: 0.8rem;
  color: var(--text-dim);
  margin-bottom: 0.3rem;
}

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text);
  padding: 0.55rem 0.75rem;
  font-size: 0.85rem;
  font-family: var(--font);
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var(--border-focus);
}

.form-group textarea {
  resize: vertical;
  min-height: 80px;
}

/* ── Modal ───────────────────────────────────────────────── */

.modal {
  position: fixed; inset: 0;
  background: rgba(0,0,0,0.6);
  display: flex; align-items: center; justify-content: center;
  z-index: 1000;
}

.modal[hidden] { display: none; }

.modal-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  width: 100%; max-width: 600px;
  max-height: 80vh;
  overflow-y: auto;
  box-shadow: var(--shadow-lg);
}

.modal-card header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 1rem 1.25rem;
  border-block-end: 1px solid var(--border);
}

.modal-card header h3 {
  font-size: 1rem;
  color: var(--text-bright);
}

#modal-body { padding: 1.25rem; }

/* ── Toast ───────────────────────────────────────────────── */

.toast {
  position: fixed;
  bottom: 1.5rem;
  inset-inline-end: 1.5rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 0.75rem 1.25rem;
  font-size: 0.85rem;
  color: var(--text);
  box-shadow: var(--shadow-lg);
  z-index: 2000;
  transform: translateY(120%);
  transition: transform 0.3s ease;
  max-width: 400px;
}

.toast.show { transform: translateY(0); }
.toast.success { border-color: var(--success); }
.toast.error { border-color: var(--danger); }

/* ── Approval Cards ──────────────────────────────────────── */

.approval-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1rem;
  margin-block-end: 0.75rem;
  transition: border-color var(--transition);
}

.approval-card:hover { border-color: var(--accent); }

.approval-meta {
  display: flex; gap: 0.5rem; flex-wrap: wrap;
  margin-block-end: 0.5rem;
}

.approval-skill {
  background: var(--accent-dim);
  color: var(--accent);
  padding: 0.15rem 0.5rem;
  border-radius: var(--radius-sm);
  font-size: 0.7rem;
  font-weight: 600;
}

.approval-confidence {
  color: var(--text-dim);
  font-size: 0.7rem;
}

.approval-actions {
  display: flex; gap: 0.5rem;
  margin-block-start: 0.75rem;
}

/* ── Status Badges ───────────────────────────────────────── */

.status {
  display: inline-block;
  padding: 0.15rem 0.5rem;
  border-radius: var(--radius-sm);
  font-size: 0.7rem;
  font-weight: 600;
}

.status-pending { background: var(--warning-dim); color: var(--warning); }
.status-approved { background: var(--success-dim); color: var(--success); }
.status-rejected { background: var(--danger-dim); color: var(--danger); }
.status-edited { background: var(--info-dim); color: var(--info); }
.status-timeout { background: var(--bg-card); color: var(--text-dim); }
.status-escalated { background: var(--warning-dim); color: var(--warning); }
.status-cancelled { background: var(--bg-card); color: var(--text-dim); }

.status-open { background: var(--info-dim); color: var(--info); }
.status-in_progress { background: var(--warning-dim); color: var(--warning); }
.status-resolved { background: var(--success-dim); color: var(--success); }
.status-closed { background: var(--bg-card); color: var(--text-dim); }
.status-draft { background: var(--bg-card); color: var(--text-dim); }
.status-sent { background: var(--info-dim); color: var(--info); }
.status-active { background: var(--success-dim); color: var(--success); }

/* ── Empty State ─────────────────────────────────────────── */

.empty {
  text-align: center;
  padding: 3rem 1rem;
  color: var(--text-dim);
}

.empty .icon {
  font-size: 2.5rem;
  margin-bottom: 0.75rem;
  opacity: 0.5;
}

/* ── Loading Spinner ─────────────────────────────────────── */

.spinner {
  display: inline-block;
  width: 1.2rem; height: 1.2rem;
  border: 2px solid var(--border);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin 0.6s linear infinite;
}

@keyframes spin { to { transform: rotate(360deg); } }

.loading-center {
  display: flex; align-items: center; justify-content: center;
  padding: 3rem;
}

/* ── RTL Overrides ──────────────────────────────────────── */

[dir="rtl"] { direction: rtl; text-align: right; }

/* ── Responsive ──────────────────────────────────────────── */

@media (max-width: 768px) {
  .side {
    position: fixed;
    inset-inline-start: 0;
    top: 0; bottom: 0;
    z-index: 500;
    transform: translateX(-100%);
    transition: transform 0.3s ease;
  }

  .side.open { transform: translateX(0); }

  [dir="rtl"] .side { transform: translateX(100%); }
  [dir="rtl"] .side.open { transform: translateX(0); }

  .grid-2, .grid-3, .grid-4 {
    grid-template-columns: 1fr;
  }

  .view { padding: 1rem; }
}

/* ── Print ───────────────────────────────────────────────── */

@media print {
  .side, .top, .modal, .toast { display: none !important; }
  .main { overflow: visible; }
  .view { padding: 0; }
  body { background: #fff; color: #000; }
}

